{"command":"cd /workspace
cat <<'PY' > /tmp/test_keywords.py
import subprocess, json

def is_bare(key):
    j = json.dumps({key:1}, ensure_ascii=False)
    out = subprocess.check_output(['./executable'], input=j.encode()).decode()
    lines = out.strip().split('\n')
    if len(lines)<2:
        return None
    line=lines[1]
    # line like json.a = 1; or json["a-b"] = 1;
    # Check if contains '["'
    return '["' not in line  # if no bracket, bare (assuming bare uses dot)
    # Actually also need to handle [""] etc but for bare test keys without special chars, this works

keywords = [
"break","case","catch","class","const","continue","debugger","default","delete","do","else","export","extends","false","finally","for","function","if","import","in","instanceof","new","null","return","super","switch","this","throw","true","try","typeof","var","void","while","with","yield","enum","implements","interface","let","package","private","protected","public","static","await","abstract","boolean","byte","char","double","final","float","goto","int","long","native","short","synchronized","throws","transient","volatile","undefined","NaN","Infinity","arguments","eval","async","of","get","set","constructor","prototype","__proto__","hasOwnProperty","toString","valueOf","let","await","yield","static","implements","interface","package","private","protected","public","enum","class","const","export","extends","import","super","null","true","false","in","instanceof","typeof","void","delete","new","this","debugger","from","as","meta","target"
]

# Remove duplicates preserve order
seen=set()
uniq=[]
for k in keywords:
    if k not in seen:
        seen.add(k)
        uniq.append(k)

for k in uniq:
    bare = is_bare(k)
    print(f"{k}: {'bare' if bare else 'quoted'}")

PY
python3 /tmp/test_keywords.py
"}

