cat > main.go <<'GO'
package main

import (
	"bufio"
	"bytes"
	"crypto/tls"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"sort"
	"strconv"
	"strings"
	"unicode"
)

var helpText = `Transform JSON (from a file, URL, or stdin) into discrete assignments to make it greppable

Usage:
  gron [OPTIONS] [FILE|URL|-]

Options:
  -u, --ungron     Reverse the operation (turn assignments back into JSON)
  -v, --values     Print just the values of provided assignments
  -c, --colorize   Colorize output (default on tty)
  -m, --monochrome Monochrome (don't colorize output)
  -s, --stream     Treat each line of input as a separate JSON object
  -k, --insecure   Disable certificate validation
  -x, --proxy      Set proxy configuration
      --noproxy    Comma-separated list of hosts for which not to use a proxy, if one is specified.
  -j, --json       Represent gron data as JSON stream
      --no-sort    Don't sort output (faster)
      --version    Print version information

Exit Codes:
  0	OK
  1	Failed to open file
  2	Failed to read input
  3	Failed to form statements
  4	Failed to fetch URL
  5	Failed to parse statements
  6	Failed to encode JSON

Examples:
  gron /tmp/apiresponse.json
  gron http://jsonplaceholder.typicode.com/users/1 
  curl -s http://jsonplaceholder.typicode.com/users/1 | gron
  gron http://jsonplaceholder.typicode.com/users/1 | grep company | gron --ungron
`

func main() {
	fs := flag.NewFlagSet(os.Args[0], flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	fs.Usage = func() {
		fmt.Fprint(os.Stderr, helpText+"\n")
	}

	var ungron bool
	var values bool
	var colorize bool
	var monochrome bool
	var stream bool
	var insecure bool
	var proxyStr string
	var noproxyStr string
	var jsonFlag bool
	var noSort bool
	var version bool
	var help bool

	// define flags
	fs.BoolVar(&ungron, "u", false, "")
	fs.BoolVar(&ungron, "ungron", false, "")

	fs.BoolVar(&values, "v", false, "")
	fs.BoolVar(&values, "values", false, "")

	fs.BoolVar(&colorize, "c", false, "")
	fs.BoolVar(&colorize, "colorize", false, "")

	fs.BoolVar(&monochrome, "m", false, "")
	fs.BoolVar(&monochrome, "monochrome", false, "")

	fs.BoolVar(&stream, "s", false, "")
	fs.BoolVar(&stream, "stream", false, "")

	fs.BoolVar(&insecure, "k", false, "")
	fs.BoolVar(&insecure, "insecure", false, "")

	fs.StringVar(&proxyStr, "x", "", "")
	fs.StringVar(&proxyStr, "proxy", "", "")

	fs.StringVar(&noproxyStr, "noproxy", "", "")

	fs.BoolVar(&jsonFlag, "j", false, "")
	fs.BoolVar(&jsonFlag, "json", false, "")

	fs.BoolVar(&noSort, "no-sort", false, "")

	fs.BoolVar(&version, "version", false, "")

	fs.BoolVar(&help, "h", false, "")
	fs.BoolVar(&help, "help", false, "")

	// parse
	err := fs.Parse(os.Args[1:])
	if err != nil {
		// flag package already printed error and usage
		os.Exit(2)
	}

	if help {
		fmt.Fprint(os.Stderr, helpText+"\n")
		os.Exit(0)
	}
	if version {
		fmt.Println("gron version dev")
		os.Exit(0)
	}

	// determine file arg
	var fileArg string
	if fs.NArg() > 0 {
		fileArg = fs.Arg(0)
	}

	// read input
	var inputBytes []byte
	var readErr error

	if fileArg == "" || fileArg == "-" {
		// stdin
		inputBytes, readErr = io.ReadAll(os.Stdin)
		if readErr != nil {
			fmt.Fprintf(os.Stderr, "failed to read input: %s\n", readErr.Error())
			os.Exit(2)
		}
	} else if strings.HasPrefix(fileArg, "http://") || strings.HasPrefix(fileArg, "https://") {
		// fetch URL
		inputBytes, readErr = fetchURL(fileArg, proxyStr, noproxyStr, insecure)
		if readErr != nil {
			// error already includes "Get ..."
			fmt.Fprintln(os.Stderr, readErr.Error())
			os.Exit(4)
		}
	} else {
		// file
		f, err := os.Open(fileArg)
		if err != nil {
			fmt.Fprintln(os.Stderr, err.Error())
			os.Exit(1)
		}
		defer f.Close()
		inputBytes, readErr = io.ReadAll(f)
		if readErr != nil {
			// treat as failed to form statements
			fmt.Fprintf(os.Stderr, "failed to form statements: %s\n", readErr.Error())
			os.Exit(3)
		}
	}

	// determine color enabled
	colorEnabled := false
	if values && !ungron {
		// bare values mode never colored (observed)
		colorEnabled = false
	} else {
		if colorize {
			colorEnabled = true
		} else if monochrome {
			colorEnabled = false
		} else {
			// auto detect tty
			if isTerminal(os.Stdout) {
				colorEnabled = true
			} else {
				colorEnabled = false
			}
		}
	}

	// Branch based on mode
	if ungron {
		if jsonFlag {
			// input is json stream of gron data
			// parse each line as json array [path, value]
			// output JSON
			handleUngronJSONStream(inputBytes, colorEnabled)
		} else {
			// input is text statements
			handleUngronText(inputBytes, colorEnabled)
		}
	} else if values {
		// input is text statements, output bare values
		handleValuesText(inputBytes)
	} else {
		// gron mode: JSON input -> statements (text or json stream)
		if stream {
			handleGronStream(inputBytes, jsonFlag, noSort, colorEnabled)
		} else {
			handleGronSingle(inputBytes, jsonFlag, noSort, colorEnabled)
		}
	}
}

func isTerminal(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func fetchURL(rawurl, proxyStr, noproxyStr string, insecure bool) ([]byte, error) {
	// parse proxy
	var proxyURL *url.URL
	var err error
	if proxyStr != "" {
		proxyURL, err = url.Parse(proxyStr)
		if err != nil {
			return nil, fmt.Errorf("Get %q: %s", rawurl, err.Error())
		}
	}

	noproxyList := []string{}
	if noproxyStr != "" {
		parts := strings.Split(noproxyStr, ",")
		for _, p := range parts {
			p = strings.TrimSpace(p)
			if p != "" {
				noproxyList = append(noproxyList, p)
			}
		}
	}

	transport := &http.Transport{
		TLSClientConfig: &tls.Config{},
	}
	if insecure {
		transport.TLSClientConfig.InsecureSkipVerify = true
	}

	// proxy func
	transport.Proxy = func(req *http.Request) (*url.URL, error) {
		if proxyURL != nil {
			// check noproxy
			host := req.URL.Hostname()
			for _, np := range noproxyList {
				if np == "*" {
					return nil, nil
				}
				if host == np {
					return nil, nil
				}
				if strings.HasSuffix(host, "."+np) {
					return nil, nil
				}
				if np != "" && strings.Contains(host, np) {
					// additional simple contains check? We'll keep exact and suffix only.
				}
			}
			return proxyURL, nil
		}
		// use env
		return http.ProxyFromEnvironment(req)
	}

	client := &http.Client{
		Transport: transport,
		Timeout:   0, // need timeout to get context deadline exceeded? Use default? Let's set 10s
	}
	// Go's default client timeout handling: we set Timeout to 10 seconds to match observed "Client.Timeout exceeded"
	client.Timeout = 10 * 1e9 // 10 seconds, using duration literal? We'll use time.
	// Actually need time import
	// We'll override below

	// Let's do time
	// We already have timeout set via our custom below.

	// Re-create with time
	// Use non-zero timeout via http.Client Timeout
	// Already set 10s as 10e9 ns = 10s

	resp, err := client.Get(rawurl)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("Get %q: %s", rawurl, err.Error())
	}
	return body, nil
}

// OrderedMap representation
type OrderedMap struct {
	Keys   []string
	Values map[string]interface{}
}

func newOrderedMap() *OrderedMap {
	return &OrderedMap{
		Keys:   []string{},
		Values: map[string]interface{}{},
	}
}

// JSON parsing with order and raw numbers

func parseJSONValue(data []byte) (interface{}, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	// parse first value
	val, err := parseValue(dec)
	if err != nil {
		return nil, err
	}
	return val, nil
}

func parseValue(dec *json.Decoder) (interface{}, error) {
	t, err := dec.Token()
	if err != nil {
		return nil, err
	}
	switch v := t.(type) {
	case json.Delim:
		switch v {
		case '{':
			// object
			om := newOrderedMap()
			for dec.More() {
				// key
				kt, err := dec.Token()
				if err != nil {
					return nil, err
				}
				key, ok := kt.(string)
				if !ok {
					return nil, fmt.Errorf("expected string key")
				}
				// value
				val, err := parseValue(dec)
				if err != nil {
					return nil, err
				}
				if _, exists := om.Values[key]; !exists {
					om.Keys = append(om.Keys, key)
				}
				om.Values[key] = val
			}
			// consume '}'
			_, err = dec.Token()
			if err != nil {
				return nil, err
			}
			return om, nil
		case '[':
			// array
			arr := []interface{}{}
			for dec.More() {
				val, err := parseValue(dec)
				if err != nil {
					return nil, err
				}
				arr = append(arr, val)
			}
			_, err = dec.Token()
			if err != nil {
				return nil, err
			}
			return arr, nil
		default:
			return nil, fmt.Errorf("unexpected delim %v", v)
		}
	case string:
		return v, nil
	case json.Number:
		return v, nil
	case bool:
		return v, nil
	case nil:
		return nil, nil
	default:
		return nil, fmt.Errorf("unexpected token %T", v)
	}
}

// For handling Gron single JSON

func handleGronSingle(input []byte, jsonFlag, noSort, colorEnabled bool) {
	// trim?
	// If input empty or whitespace only, error EOF
	if len(bytes.TrimSpace(input)) == 0 {
		fmt.Fprintln(os.Stderr, "failed to form statements: EOF")
		os.Exit(3)
	}
	val, err := parseJSONValue(input)
	if err != nil {
		// need to format error message as original: "failed to form statements: <err>"
		// Go's json errors include "invalid character..." etc. Original messages use those.
		fmt.Fprintf(os.Stderr, "failed to form statements: %s\n", err.Error())
		os.Exit(3)
	}
	stmts := []Statement{}
	genStatements("json", []interface{}{}, val, &stmts, noSort)

	if jsonFlag {
		// output json stream
		for _, st := range stmts {
			// path slice already in st.PathSlice
			// value for json stream: st.ValueForJSON
			line := st.JSONLine(colorEnabled)
			fmt.Println(line)
		}
	} else {
		// text
		// sort statements if needed? Our gen already generates in sorted order via sorted keys, but need to ensure statements sorted globally? According to earlier, DFS with sorted keys already yields sorted order, but we should also sort statements by path for safety if needed? Let's see if gen with sorted keys already yields sorted. We'll trust gen.
		// However original sorts statements after generation? Let's check if sorting of statements is separate from key sorting. For no-sort, they preserve input order. For sort, they sort keys and thus statements. So gen does it.
		// But we also need to handle sorting of statements when there are duplicate keys? Already handled.
		// For text mode, we may need to sort statements by text representation? But DFS sorted should equal text sorted? Might need extra sorting by path string? Let's test: For object {"b":1,"a":2}, DFS sorted gives json={}, json.a, json.b – lexicographically sorted as well. For more complex, DFS sorted should be same as lexicographic sort of path strings? Possibly yes.
		// We'll output as generated, but if not noSort, we should sort statements by path lexicographically as fallback? Let's see if DFS with sorted keys always produces lexicographically sorted paths. For array, indices numeric sorted matches lexicographic? For array indices up to 12, numeric order is not lexicographic string order, but our earlier test showed array indices 0..12 numeric order, not lexicographic "0,1,10,11,12,2...". So sorting by path string lexicographically would give wrong order for arrays. So we must NOT sort by path string, but by structural path comparison (numeric for array indices). Our gen with DFS sorted keys and array index order numeric already gives correct order.

		// However, what about object keys that are not bare, like "a-b" vs "a"? Lexicographic order of path strings: "json.a" vs "json[\"a-b\"]" – which comes first? Space vs dot vs bracket? Our earlier test: {"a":1,"a-b":2} sorted gave json.a first, then json["a-b"] – because "json.a" < "json[\"a-b\"]"? Let's check ASCII: '.' is 46, '[' is 91, so '.' < '[' so "json.a" < "json[..." – so a before a-b, which matches.

		// So DFS sorted keys should already produce lexicographically plausible order, but we need to ensure sorting of object keys lexicographically produces same as statement sorting? For keys "a" and "a-b", lexicographic key sorting: "a" < "a-b" (since shorter prefix). So DFS with sorted keys gives a before a-b, same.

		// So we will just output stmts in order generated, but we should sort stmts by path using structural comparator if not noSort? Actually gen already sorts keys, so stmts are sorted. But to be safe, we should sort stmts after generation using our path comparator if !noSort.

		// For simplicity, if !noSort, we will sort stmts by path using comparator.

		if !noSort {
			sort.Slice(stmts, func(i, j int) bool {
				return comparePaths(stmts[i].PathSlice, stmts[j].PathSlice) < 0
			})
		}

		for _, st := range stmts {
			fmt.Println(st.TextLine(colorEnabled))
		}
	}
}

func handleGronStream(input []byte, jsonFlag, noSort, colorEnabled bool) {
	// If input empty => empty array
	if len(input) == 0 {
		// empty array
		stmts := []Statement{}
		genStatements("json", []interface{}{}, []interface{}{}, &stmts, noSort)
		if jsonFlag {
			for _, st := range stmts {
				fmt.Println(st.JSONLine(colorEnabled))
			}
		} else {
			if !noSort {
				sort.Slice(stmts, func(i, j int) bool {
					return comparePaths(stmts[i].PathSlice, stmts[j].PathSlice) < 0
				})
			}
			for _, st := range stmts {
				fmt.Println(st.TextLine(colorEnabled))
			}
		}
		return
	}

	// Use scanner to read lines
	scanner := bufio.NewScanner(bytes.NewReader(input))
	// Increase buffer size for large lines
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 10*1024*1024)

	var values []interface{}
	var firstErr error
	var firstErrLine string

	for scanner.Scan() {
		line := scanner.Text()
		// line is without newline, may contain leading/trailing spaces
		// If line is empty? We'll attempt to parse and handle error
		// Use parseJSONValue on line bytes
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			// This will cause EOF error when parsing
			// To match original error message "failed to form statements: EOF", we need to try to parse and get error
			// For blank line, json.Unmarshal returns EOF
			_, err := parseJSONValue([]byte(line))
			if err != nil {
				firstErr = err
				firstErrLine = line
				break
			} else {
				// shouldn't happen
				continue
			}
		}
		val, err := parseJSONValue([]byte(line))
		if err != nil {
			firstErr = err
			firstErrLine = line
			break
		}
		values = append(values, val)
	}
	if err := scanner.Err(); err != nil {
		// scanner error (too long line etc)
		fmt.Fprintf(os.Stderr, "failed to form statements: %s\n", err.Error())
		os.Exit(3)
	}

	// If firstErr != nil, we have partial values collected, need to output gron for them, then error and exit 3
	if firstErr != nil {
		// generate statements for array of collected values
		stmts := []Statement{}
		genStatements("json", []interface{}{}, values, &stmts, noSort)
		if jsonFlag {
			for _, st := range stmts {
				fmt.Println(st.JSONLine(colorEnabled))
			}
		} else {
			if !noSort {
				sort.Slice(stmts, func(i, j int) bool {
					return comparePaths(stmts[i].PathSlice, stmts[j].PathSlice) < 0
				})
			}
			for _, st := range stmts {
				fmt.Println(st.TextLine(colorEnabled))
			}
		}
		fmt.Fprintf(os.Stderr, "failed to form statements: %s\n", firstErr.Error())
		os.Exit(3)
	}

	// No error, all lines parsed
	stmts := []Statement{}
	genStatements("json", []interface{}{}, values, &stmts, noSort)
	if jsonFlag {
		for _, st := range stmts {
			fmt.Println(st.JSONLine(colorEnabled))
		}
	} else {
		if !noSort {
			sort.Slice(stmts, func(i, j int) bool {
				return comparePaths(stmts[i].PathSlice, stmts[j].PathSlice) < 0
			})
		}
		for _, st := range stmts {
			fmt.Println(st.TextLine(colorEnabled))
		}
	}
}

// Statement representation

type Statement struct {
	PathStr      string
	PathSlice    []interface{} // for json stream: []interface{} of string/int
	Kind         int           // 0 empty object, 1 empty array, 2 primitive
	Primitive    interface{}   // for kind 2: nil, bool, string, json.Number
}

const (
	KindEmptyObject = 0
	KindEmptyArray  = 1
	KindPrimitive   = 2
)

func (s Statement) TextLine(color bool) string {
	// value string
	var valStr string
	var valColored string

	switch s.Kind {
	case KindEmptyObject:
		if color {
			valStr = "\x1b[35m{}\x1b[0m"
		} else {
			valStr = "{}"
		}
	case KindEmptyArray:
		if color {
			valStr = "\x1b[35m[]\x1b[0m"
		} else {
			valStr = "[]"
		}
	case KindPrimitive:
		valStr = formatPrimitiveForText(s.Primitive, color)
	}

	// path colored
	pathColored := s.PathStr
	if color {
		pathColored = colorizePathText(s.PathStr, s.PathSlice)
	}

	if color {
		return fmt.Sprintf("%s = %s;", pathColored, valStr)
	} else {
		return fmt.Sprintf("%s = %s;", s.PathStr, formatPrimitiveForText(s.Primitive, false))
	}
}

func formatPrimitiveForText(v interface{}, color bool) string {
	switch x := v.(type) {
	case nil:
		if color {
			return "\x1b[36mnull\x1b[0m"
		}
		return "null"
	case bool:
		if x {
			if color {
				return "\x1b[36mtrue\x1b[0m"
			}
			return "true"
		} else {
			if color {
				return "\x1b[36mfalse\x1b[0m"
			}
			return "false"
		}
	case string:
		// marshal with escape html false
		b, _ := marshalJSONWithEscape(x)
		s := string(b)
		if color {
			return "\x1b[33m" + s + "\x1b[0m"
		}
		return s
	case json.Number:
		// raw
		str := x.String()
		if color {
			return "\x1b[31m" + str + "\x1b[0m"
		}
		return str
	default:
		// should not happen
		b, _ := marshalJSONWithEscape(v)
		s := string(b)
		if color {
			// try to detect type for color? For safety, return s
			return s
		}
		return s
	}
}

func marshalJSONWithEscape(v interface{}) ([]byte, error) {
	buf := &bytes.Buffer{}
	enc := json.NewEncoder(buf)
	enc.SetEscapeHTML(false)
	err := enc.Encode(v)
	if err != nil {
		return nil, err
	}
	// encoder adds newline
	b := buf.Bytes()
	b = bytes.TrimSpace(b)
	return b, nil
}

func colorizePathText(pathStr string, pathSlice []interface{}) string {
	// pathStr is like "json", "json.a", "json[0]", "json[\"a-b\"]", "json.a[0].b" etc.
	// We have pathSlice which is slice of components (excluding root "json"), but we need to rebuild colored version using components.
	// Simpler: we can reconstruct colored path from pathSlice and knowledge of bare identifiers.

	// pathSlice is []interface{} where each element is string (key) or int (index)
	// For root, pathSlice empty => path is just "json"

	// For each component, check if it's string and is bare -> dot + blue, else bracket.

	// We'll produce colored path.

	// Root "json" blue bold
	blueStart := "\x1b[34;1m"
	blueEnd := "\x1b[0;22m"
	magentaStart := "\x1b[35m"
	magentaEnd := "\x1b[0m"
	yellowStart := "\x1b[33m"
	yellowEnd := "\x1b[0m"
	redStart := "\x1b[31m"
	redEnd := "\x1b[0m"

	var sb strings.Builder
	sb.WriteString(blueStart + "json" + blueEnd)

	for _, comp := range pathSlice {
		switch c := comp.(type) {
		case string:
			if isBareIdentifier(c) {
				sb.WriteString(".")
				sb.WriteString(blueStart + c + blueEnd)
			} else {
				// bracket with json marshaled key
				b, _ := marshalJSONWithEscape(c)
				sb.WriteString(magentaStart + "[" + magentaEnd)
				sb.WriteString(yellowStart + string(b) + yellowEnd)
				sb.WriteString(magentaStart + "]" + magentaEnd)
			}
		case int:
			sb.WriteString(magentaStart + "[" + magentaEnd)
			sb.WriteString(redStart + strconv.Itoa(c) + redEnd)
			sb.WriteString(magentaStart + "]" + magentaEnd)
		case float64:
			// shouldn't happen for path, but handle
			i := int(c)
			sb.WriteString(magentaStart + "[" + magentaEnd)
			sb.WriteString(redStart + strconv.Itoa(i) + redEnd)
			sb.WriteString(magentaStart + "]" + magentaEnd)
		}
	}
	return sb.String()
}

func (s Statement) JSONLine(color bool) string {
	// produce JSON array [path, value]
	// path is s.PathSlice as JSON array
	// value is s.Kind etc

	// For color disabled, just marshal [path, value] compact
	if !color {
		// need to produce JSON line preserving raw numbers
		// Build value for JSON
		var val interface{}
		switch s.Kind {
		case KindEmptyObject:
			val = map[string]interface{}{}
		case KindEmptyArray:
			val = []interface{}{}
		case KindPrimitive:
			val = s.Primitive
		}

		// path slice is []interface{} of string/int
		combined := []interface{}{s.PathSlice, val}
		b, _ := marshalJSONWithEscape(combined)
		return string(b)
	} else {
		// colored version
		// Produce outer [ , path , , value , ] with colors

		magentaStart := "\x1b[35m"
		magentaEnd := "\x1b[0m"
		yellowStart := "\x1b[33m"
		yellowEnd := "\x1b[0m"
		redStart := "\x1b[31m"
		redEnd := "\x1b[0m"
		cyanStart := "\x1b[36m"
		cyanEnd := "\x1b[0m"

		var sb strings.Builder
		sb.WriteString(magentaStart + "[" + magentaEnd)

		// path array
		sb.WriteString(magentaStart + "[" + magentaEnd)
		for i, comp := range s.PathSlice {
			if i > 0 {
				sb.WriteString(",")
			}
			switch c := comp.(type) {
			case string:
				b, _ := marshalJSONWithEscape(c)
				sb.WriteString(yellowStart + string(b) + yellowEnd)
			case int:
				sb.WriteString(redStart + strconv.Itoa(c) + redEnd)
			}
		}
		sb.WriteString(magentaStart + "]" + magentaEnd)

		sb.WriteString(",")

		// value
		switch s.Kind {
		case KindEmptyObject:
			sb.WriteString(magentaStart + "{}" + magentaEnd)
		case KindEmptyArray:
			sb.WriteString(magentaStart + "[]" + magentaEnd)
		case KindPrimitive:
			switch x := s.Primitive.(type) {
			case nil:
				sb.WriteString(cyanStart + "null" + cyanEnd)
			case bool:
				if x {
					sb.WriteString(cyanStart + "true" + cyanEnd)
				} else {
					sb.WriteString(cyanStart + "false" + cyanEnd)
				}
			case string:
				b, _ := marshalJSONWithEscape(x)
				sb.WriteString(yellowStart + string(b) + yellowEnd)
			case json.Number:
				sb.WriteString(redStart + x.String() + redEnd)
			}
		}

		sb.WriteString(magentaStart + "]" + magentaEnd)
		return sb.String()
	}
}

func comparePaths(a, b []interface{}) int {
	// returns -1 if a<b, 0 if equal, 1 if a>b
	la := len(a)
	lb := len(b)
	min := la
	if lb < min {
		min = lb
	}
	for i := 0; i < min; i++ {
		av := a[i]
		bv := b[i]
		// compare
		switch avc := av.(type) {
		case string:
			switch bvc := bv.(type) {
			case string:
				if avc < bvc {
					return -1
				} else if avc > bvc {
					return 1
				}
			case int:
				// string vs int: define string < int? Let's put string < int
				return -1
			}
		case int:
			switch bvc := bv.(type) {
			case int:
				if avc < bvc {
					return -1
				} else if avc > bvc {
					return 1
				}
			case string:
				return 1 // int > string
			}
		}
	}
	// all equal up to min, shorter is smaller
	if la < lb {
		return -1
	} else if la > lb {
		return 1
	}
	return 0
}

func genStatements(pathStr string, pathSlice []interface{}, val interface{}, out *[]Statement, noSort bool) {
	switch v := val.(type) {
	case *OrderedMap:
		if len(v.Keys) == 0 {
			// empty object
			*out = append(*out, Statement{PathStr: pathStr, PathSlice: pathSlice, Kind: KindEmptyObject})
		} else {
			// empty object marker for this path
			*out = append(*out, Statement{PathStr: pathStr, PathSlice: pathSlice, Kind: KindEmptyObject})
			keys := v.Keys
			if !noSort {
				// sort copy
				sorted := make([]string, len(keys))
				copy(sorted, keys)
				sort.Strings(sorted)
				keys = sorted
			}
			for _, k := range keys {
				childVal, ok := v.Values[k]
				if !ok {
					continue
				}
				var childPathStr string
				if isBareIdentifier(k) {
					childPathStr = pathStr + "." + k
				} else {
					b, _ := marshalJSONWithEscape(k)
					childPathStr = pathStr + "[" + string(b) + "]"
				}
				childPathSlice := append(append([]interface{}{}, pathSlice...), k)
				genStatements(childPathStr, childPathSlice, childVal, out, noSort)
			}
		}
	case []interface{}:
		if len(v) == 0 {
			*out = append(*out, Statement{PathStr: pathStr, PathSlice: pathSlice, Kind: KindEmptyArray})
		} else {
			*out = append(*out, Statement{PathStr: pathStr, PathSlice: pathSlice, Kind: KindEmptyArray})
			for i, elem := range v {
				childPathStr := pathStr + "[" + strconv.Itoa(i) + "]"
				childPathSlice := append(append([]interface{}{}, pathSlice...), i)
				genStatements(childPathStr, childPathSlice, elem, out, noSort)
			}
		}
	case nil:
		*out = append(*out, Statement{PathStr: pathStr, PathSlice: pathSlice, Kind: KindPrimitive, Primitive: nil})
	case bool:
		*out = append(*out, Statement{PathStr: pathStr, PathSlice: pathSlice, Kind: KindPrimitive, Primitive: v})
	case string:
		*out = append(*out, Statement{PathStr: pathStr, PathSlice: pathSlice, Kind: KindPrimitive, Primitive: v})
	case json.Number:
		*out = append(*out, Statement{PathStr: pathStr, PathSlice: pathSlice, Kind: KindPrimitive, Primitive: v})
	default:
		// unexpected, try to handle as string?
		*out = append(*out, Statement{PathStr: pathStr, PathSlice: pathSlice, Kind: KindPrimitive, Primitive: fmt.Sprintf("%v", v)})
	}
}

var reservedWords = map[string]bool{
	"break": true, "case": true, "catch": true, "class": true, "const": true,
	"continue": true, "debugger": true, "default": true, "delete": true, "do": true,
	"else": true, "export": true, "extends": true, "false": true, "finally": true,
	"for": true, "function": true, "if": true, "import": true, "in": true,
	"instanceof": true, "new": true, "null": true, "return": true, "super": true,
	"switch": true, "this": true, "throw": true, "true": true, "try": true,
	"typeof": true, "var": true, "void": true, "while": true, "with": true,
	"yield": true,
}

func isBareIdentifier(s string) bool {
	if s == "" {
		return false
	}
	if reservedWords[s] {
		return false
	}
	for i, r := range s {
		if i == 0 {
			if r == '_' || r == '$' || unicode.IsLetter(r) {
				continue
			}
			return false
		} else {
			if r == '_' || r == '$' || unicode.IsLetter(r) || unicode.IsDigit(r) {
				continue
			}
			return false
		}
	}
	return true
}

