			errorMsg = fmt.Sprintf("ungron failed for `%s`: statement has no value", line)
			errorOccurred = true
			break
		}

		// statement up to semicolon inclusive, but we will extract up to semiIdx
		stmtStr := line[:semiIdx+1] // includes semicolon

		// The rest after semicolon ignored

		// Now parse stmtStr
		ps, parseErr := parseGronStatement(stmtStr)
