			// So backticks contain "json." (path), not full statement.

			// For 'json..a = 1;' -> error 'json.' again.

			// For 'json.a..b = 1;' -> error 'json.a.' (path up to second dot)

			// For 'json[ = 1;' -> error 'json['

			// So for invalid path errors, backticks contain up to failure point, not full statement.

			// For statement has no value errors, backticks contain the line without semicolon? Example: 'json.a = 1' -> backticks 'json.a = 1' (no semicolon).

			// For 'json.a = ' -> backticks 'json.a = ' (with trailing space)

			// For 'json.a = ;' -> backticks 'json.a = ;' with error "invalid value ``"

			// For 'json.a = {;' -> backticks 'json.a = {;' with error "invalid value `{`"

			// So error message backticks content depends on error type.

			// Our parseGronStatement should return appropriate backticks content and reason.

			errorMsg = parseErr
			errorOccurred = true
			break
		}

		collected = append(collected, ps)
	}

	if errorOccurred {
		fmt.Fprintln(os.Stderr, errorMsg)
		os.Exit(5)
	}

	if len(collected) == 0 {
		fmt.Fprintln(os.Stderr, "no statements were parsed")
		os.Exit(5)
	}

	// Merge statements into JSON value
	merged, err := mergeStatements(collected)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to merge statements: %s\n", err.Error())
		os.Exit(5)
	}

	// Output JSON pretty
	outputJSON(merged, colorEnabled)
}

