func findSemicolonOutsideString(s string) int {
	inStr := false
	esc := false
	for i, r := range s {
		if esc {
			esc = false
			continue
		}
		if r == '\\' {
			if inStr {
				esc = true
			}
			continue
		}
		if r == '"' {
			inStr = !inStr
			continue
		}
		if !inStr && r == ';' {
			return i
		}
	}
	return -1
}

func findEqualOutsideString(s string) int {
	inStr := false
	esc := false
	for i, r := range s {
		if esc {
			esc = false
			continue
		}
		if r == '\\' {
			if inStr {
				esc = true
			}
			continue
		}
		if r == '"' {
			inStr = !inStr
			continue
		}
		if !inStr && r == '=' {
			return i
		}
	}
	return -1
}

