			// Our parseGronStatement should return appropriate backticks content and reason.

			errorMsg = parseErr
			errorOccurred = true
			break
		}

		collected = append(collected, ps)
	}

	if errorOccurred {
		fmt.Fprintln(os.Stderr, errorMsg)
		os.Exit(5)
	}

	if len(collected) == 0 {
		fmt.Fprintln(os.Stderr, "no statements were parsed")
		os.Exit(5)
	}

	// Merge statements into JSON value
	merged, err := mergeStatements(collected)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to merge statements: %s\n", err.Error())
		os.Exit(5)
