				// So if we encounter non-empty map, it's probably not expected, but we can handle as generic value.
				ps.IsEmptyObject = true // fallback?
				if len(vv) != 0 {
					// Try to parse as ordered map? Could be nested? But in json stream, non-empty object should not appear. We'll treat as empty object marker still and ignore content? Better to handle as error? Let's treat as empty object.
					ps.IsEmptyObject = true
				}
			}
		case []interface{}:
			if len(vv) == 0 {
				ps.IsEmptyArray = true
			} else {
				// Similarly, non-empty array should not appear as value in json stream (only [] marker). So treat as empty array?
				ps.IsEmptyArray = true
			}
		case nil:
			ps.Primitive = nil
		case bool:
			ps.Primitive = vv
		case string:
			ps.Primitive = vv
		case json.Number:
			ps.Primitive = vv
