// Ungron

func handleUngronText(input []byte, colorEnabled bool) {
	lines := strings.Split(string(input), "\n")
	var parsed []ParsedStatement

	for _, rawLine := range lines {
		line := rawLine
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, " ") {
			continue
		}
		if strings.HasPrefix(line, "\t") {
			fmt.Fprintln(os.Stderr, "ungron failed for ``: invalid statement")
			os.Exit(5)
		}
		semiIdx := findSemicolonOutsideString(line)
		if semiIdx == -1 {
			fmt.Fprintf(os.Stderr, "ungron failed for `%s`: statement has no value\n", line)
			os.Exit(5)
		}
		stmtStr := line[:semiIdx+1]
		ps, errMsg := parseGronStatement(stmtStr)
		if errMsg != "" {
			fmt.Fprintln(os.Stderr, errMsg)
			os.Exit(5)
		}
		parsed = append(parsed, ps)
	}

	if len(parsed) == 0 {
		fmt.Fprintln(os.Stderr, "no statements were parsed")
		os.Exit(5)
	}

	merged, err := mergeStatements(parsed)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to merge statements: %s\n", err.Error())
		os.Exit(5)
	}

	outputJSON(merged, colorEnabled)
}

func handleUngronJSONStream(input []byte, colorEnabled bool) {
	lines := strings.Split(string(input), "\n")
	var parsed []ParsedStatement

	for _, rawLine := range lines {
		line := strings.TrimSpace(rawLine)
		if line == "" {
			continue
		}
		var arr []interface{}
		dec := json.NewDecoder(strings.NewReader(line))
		dec.UseNumber()
		if err := dec.Decode(&arr); err != nil {
			fmt.Fprintln(os.Stderr, err.Error())
			os.Exit(5)
		}
		if len(arr) != 2 {
			fmt.Fprintln(os.Stderr, "invalid statement")
			os.Exit(5)
		}
		pathRaw, ok := arr[0].([]interface{})
		if !ok {
			fmt.Fprintln(os.Stderr, "invalid statement")
			os.Exit(5)
		}
		path := []interface{}{}
		for _, p := range pathRaw {
			switch v := p.(type) {
			case string:
				path = append(path, v)
			case json.Number:
				i, err := v.Int64()
				if err == nil {
					path = append(path, int(i))
				} else {
					f, _ := v.Float64()
					path = append(path, int(f))
				}
			case float64:
				path = append(path, int(v))
			default:
				path = append(path, fmt.Sprintf("%v", v))
			}
		}
		val := arr[1]
		ps := ParsedStatement{Path: path}
		switch vv := val.(type) {
		case map[string]interface{}:
			if len(vv) == 0 {
				ps.IsEmptyObject = true
			} else {
				// treat as empty object? For safety, convert to our structure? But in json stream gron, non-empty object should not appear as value; however if it does, we attempt to handle by creating ordered map? For simplicity, treat as empty object
				ps.IsEmptyObject = true
			}
		case []interface{}:
			if len(vv) == 0 {
				ps.IsEmptyArray = true
			} else {
				ps.IsEmptyArray = true
			}
		case nil:
			ps.Primitive = nil
		case bool:
			ps.Primitive = vv
		case string:
			ps.Primitive = vv
		case json.Number:
			ps.Primitive = vv
		default:
			ps.Primitive = vv
		}
		parsed = append(parsed, ps)
	}

	if len(parsed) == 0 {
		fmt.Fprintln(os.Stderr, "no statements were parsed")
		os.Exit(5)
	}

	merged, err := mergeStatements(parsed)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to merge statements: %s\n", err.Error())
		os.Exit(5)
	}

	outputJSON(merged, colorEnabled)
}

