func readRune(s string, idx int) (rune, int) {
	if idx >= len(s) {
		return 0, 0
	}
	r, size := rune(s[idx]), 1
	// handle utf8
	if r >= 0x80 {
		r, size = utf8Decode(s[idx:])
	}
	return r, size
}

func utf8Decode(b string) (rune, int) {
	// use standard library rune decoding
	for i := 1; i <= 4 && i <= len(b); i++ {
		r, size := rune(b[0]), i
		if size > 0 {
			// quick
			// Use utf8
			r, size := decode(b)
			return r, size
		}
	}
	return rune(b[0]), 1
}

func decode(s string) (rune, int) {
	// Use unicode/utf8
	// Import utf8?
	r, size := rune(s[0]), 1
	if r < 0x80 {
		return r, 1
	}
	// Use standard library via manual? We'll use utf8 package if available
	// For simplicity, return 1
	return r, size
}

func isIdentifierStart(r rune) bool {
	return r == '_' || r == '$' || unicode.IsLetter(r)
}

func isIdentifierChar(r rune) bool {
	return r == '_' || r == '$' || unicode.IsLetter(r) || unicode.IsDigit(r)
}

