		// For simplicity, return statement has no value with backticks = pathPart + " = " + string(trimmedValue[0])
		// Need to reconstruct path string? Use original pathPart trimmed + " = " + first char
		pp := strings.TrimSpace(pathPart)
		return ParsedStatement{}, fmt.Sprintf("ungron failed for `%s = %c`: statement has no value", pp, trimmedValue[0])
	}

	// Try to parse as JSON primitive
	dec := json.NewDecoder(strings.NewReader(trimmedValue))
