		// Try to see if trimmedValue starts with number, we allow extra junk for numbers as per earlier
		// For numbers, we should extract number prefix
		if isNumberStart(trimmedValue) {
			numStr := extractNumberPrefix(trimmedValue)
			if numStr != "" {
				// parse as json.Number
				n := json.Number(numStr)
				// check if there is extra after number that is not allowed for non-number? For numbers, extra allowed
				return ParsedStatement{Path: pathSlice, Primitive: n}, ""
			}
		}
		// invalid value
		return ParsedStatement{}, fmt.Sprintf("ungron failed for `%s`: invalid value `%s`", stmt, trimmedValue)
	}
	// Check remaining after first value
	// Use dec.Buffered() to see remaining? Simpler: try to decode remaining and if more than whitespace, then for non-number it should error
	// For our purposes, after decoding first value, we should check if there is extra non-whitespace before semicolon.

	// Get remaining bytes from decoder's buffered + input
	// Simpler: we have trimmedValue, and we have consumed some bytes (we don't know how many). We can try to marshal v back to JSON and compare length? Not reliable for numbers.

	// For simplicity, if after decoding, there is leftover that is not just spaces, then:
