func parsePath(s string) ([]interface{}, string, string) {
	orig := s
	s = strings.TrimSpace(s)
	if s == "" {
		return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", orig)
	}
	var path []interface{}
	i := 0
	// parse first component
	start := i
	if i >= len(s) {
		return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(orig, i))
	}
	r, size := utf8.DecodeRuneInString(s[i:])
	if !isIdentifierStart(r) {
		return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i))
	}
	i += size
	for i < len(s) {
		r, size := utf8.DecodeRuneInString(s[i:])
		if isIdentifierChar(r) {
			i += size
		} else {
			break
		}
	}
	ident := s[start:i]
	path = append(path, ident)

	for i < len(s) {
		// skip spaces
		for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
			i++
		}
		if i >= len(s) {
			break
		}
		ch := s[i]
		if ch == '.' {
			i++
			if i >= len(s) {
				return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i))
			}
			if s[i] == '.' {
				return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i-1))
			}
			start2 := i
			r, _ := utf8.DecodeRuneInString(s[i:])
			if !isIdentifierStart(r) {
				return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, start2-1))
			}
			// parse identifier
			for i < len(s) {
				r, size := utf8.DecodeRuneInString(s[i:])
				if isIdentifierChar(r) {
					i += size
				} else {
					break
				}
			}
			ident2 := s[start2:i]
			path = append(path, ident2)
		} else if ch == '[' {
			i++
			// skip spaces
			for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
				i++
			}
			if i >= len(s) {
				return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i-1))
			}
			if s[i] == '"' {
				// string key
				strStart := i
				j := i + 1
				esc := false
				found := false
				for j < len(s) {
					c := s[j]
					if esc {
						esc = false
						j++
						continue
					}
					if c == '\\' {
						esc = true
						j++
						continue
					}
					if c == '"' {
						found = true
						break
					}
					j++
				}
				if !found {
					return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", s[:strStart])
				}
				strLit := s[strStart : j+1]
				var key string
				if err := json.Unmarshal([]byte(strLit), &key); err != nil {
					return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", s[:j+1])
				}
				path = append(path, key)
				i = j + 1
				// skip spaces
				for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
					i++
				}
				if i >= len(s) || s[i] != ']' {
					return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i))
				}
				i++
			} else if s[i] >= '0' && s[i] <= '9' {
				numStart := i
				for i < len(s) && s[i] >= '0' && s[i] <= '9' {
					i++
				}
				numStr := s[numStart:i]
				idx, _ := strconv.Atoi(numStr)
				path = append(path, idx)
				for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
					i++
				}
				if i >= len(s) || s[i] != ']' {
					return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i))
				}
				i++
			} else {
				return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i-1))
			}
		} else {
			break
		}
	}

	remaining := strings.TrimSpace(s[i:])
	if remaining != "" {
		// extra after path before "=" should be considered as not part of path? Actually for "json.a 1", after parsing "json.a", remaining "1" would be non-empty, but we want to treat as missing "="
		// So we return path and remaining
		// Caller will handle missing "="
	}

	// handle root json special for merging? We do it in caller? Actually parsePath returns path including json, then we strip json in parseGronStatement
	// For error messages, we need partial path as s[:i]?

	// For merging, we will strip json later

	// Return path and remaining
	// For success, remaining should be empty (or spaces)
	// But we already trimmed spaces, so remaining should be empty for valid path
	// If remaining non-empty, it's not valid path? But for "json.a 1", path "json.a" and remaining "1" -> we would consider path valid and remaining "1" will be handled as missing "=" in caller, which is correct.

	// So we return path and remaining = s[i:] (original not trimmed?) Let's return the rest of original string after path parsing (including spaces)

	// Actually we have s as trimmed version, and i is index in trimmed s
	// The remaining part after path in original orig may include spaces, but we have trimmed, so we return remaining trimmed? We'll return s[i:] as remaining

	// For error messages, we need to produce partial path up to failure, not full

	// For valid path, return path, remainder, no error

	// Strip json handling done in parseGronStatement

	if len(path) > 0 {
		if first, ok := path[0].(string); ok && first == "json" {
			path = path[1:]
		}
	}

	return path, s[i:], ""
}

func getPartialPath(s string, idx int) string {
	if idx < 0 {
		idx = 0
	}
	if idx > len(s) {
		idx = len(s)
	}
	return s[:idx]
}

