	redEnd := "\x1b[0m"
	cyanStart := "\x1b[36m"
	cyanEnd := "\x1b[0m"
	boldStart := "\x1b[1m"
	boldEnd := "\x1b[22m"
	greenStart := "\x1b[32m"
	greenEnd := "\x1b[0m"

