func isNumberStart(s string) bool {
	if s == "" {
		return false
	}
	c := s[0]
	return (c >= '0' && c <= '9') || c == '-'
}

func extractNumberPrefix(s string) string {
	// regex for JSON number prefix: -?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][-+]?[0-9]+)?
	// We'll manually parse

	i := 0
	if i < len(s) && s[i] == '-' {
		i++
	}
	if i >= len(s) {
		return ""
	}
	// int part
	if s[i] == '0' {
		i++
	} else if s[i] >= '1' && s[i] <= '9' {
		i++
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			i++
		}
	} else {
		return ""
	}
	// frac
	if i < len(s) && s[i] == '.' {
		// need at least one digit after
		if i+1 < len(s) && s[i+1] >= '0' && s[i+1] <= '9' {
			i++ // dot
			for i < len(s) && s[i] >= '0' && s[i] <= '9' {
				i++
			}
		} else {
			// dot not followed by digit, so number ends before dot
			// For "1.2.3", after "1", we have ".2.3" – first char '.' and next '2' digit, so frac would be ".2", so we would continue
			// Actually we are at dot, need to check
			// If dot and next is digit, we consume ".2"
			// So we already did? Wait we are at dot, we check next digit, if exists we consume
			// So for "1.2.3", i at dot after "1", next char '2' digit, so we consume ".2", i now at dot before "3"
			// Then we would have ".3" remaining as extra, which is allowed to be ignored
			// So we consumed ".2"
		}
	}
	// exp
	if i < len(s) && (s[i] == 'e' || s[i] == 'E') {
		j := i + 1
		if j < len(s) && (s[j] == '+' || s[j] == '-') {
			j++
		}
		if j < len(s) && s[j] >= '0' && s[j] <= '9' {
			// valid exp
			i = j + 1
			for i < len(s) && s[i] >= '0' && s[i] <= '9' {
				i++
			}
		} else {
			// e not followed by digit, so exp not consumed, number ends before e?
			// For "1e", number "1" valid, e is extra? But original allows "1e10" etc, but "1e" alone would be "1" with extra "e"? Let's see. For "1e", number prefix "1" should be valid.
			// So we should not consume e if not followed by digit
		}
	}
	return s[:i]
}

func parsePath(s string) ([]interface{}, string, string) {
	orig := s
	s = strings.TrimSpace(s)
	if s == "" {
		return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", orig)
	}
	var path []interface{}
	i := 0
	// parse first component
	start := i
	if i >= len(s) {
		return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(orig, i))
	}
	r, size := utf8.DecodeRuneInString(s[i:])
	if !isIdentifierStart(r) {
		return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i))
	}
	i += size
	for i < len(s) {
		r, size := utf8.DecodeRuneInString(s[i:])
		if isIdentifierChar(r) {
			i += size
		} else {
			break
		}
	}
	ident := s[start:i]
	path = append(path, ident)

	for i < len(s) {
		// skip spaces
		for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
			i++
		}
		if i >= len(s) {
			break
		}
		ch := s[i]
		if ch == '.' {
			i++
			if i >= len(s) {
				return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i))
			}
			if s[i] == '.' {
				return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i-1))
			}
			start2 := i
			r, _ := utf8.DecodeRuneInString(s[i:])
			if !isIdentifierStart(r) {
				return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, start2-1))
			}
			// parse identifier
			for i < len(s) {
				r, size := utf8.DecodeRuneInString(s[i:])
				if isIdentifierChar(r) {
					i += size
				} else {
					break
				}
			}
			ident2 := s[start2:i]
			path = append(path, ident2)
		} else if ch == '[' {
			i++
			// skip spaces
			for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
				i++
			}
			if i >= len(s) {
				return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i-1))
			}
			if s[i] == '"' {
				// string key
				strStart := i
				j := i + 1
				esc := false
				found := false
				for j < len(s) {
					c := s[j]
					if esc {
						esc = false
						j++
						continue
					}
					if c == '\\' {
						esc = true
						j++
						continue
					}
					if c == '"' {
						found = true
						break
					}
					j++
				}
				if !found {
					return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", s[:strStart])
				}
				strLit := s[strStart : j+1]
				var key string
				if err := json.Unmarshal([]byte(strLit), &key); err != nil {
					return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", s[:j+1])
				}
				path = append(path, key)
				i = j + 1
				// skip spaces
				for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
					i++
				}
				if i >= len(s) || s[i] != ']' {
					return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i))
				}
				i++
			} else if s[i] >= '0' && s[i] <= '9' {
				numStart := i
				for i < len(s) && s[i] >= '0' && s[i] <= '9' {
					i++
				}
				numStr := s[numStart:i]
				idx, _ := strconv.Atoi(numStr)
				path = append(path, idx)
				for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
					i++
				}
				if i >= len(s) || s[i] != ']' {
					return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i))
				}
				i++
			} else {
				return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i-1))
			}
		} else {
			break
		}
	}

	remaining := strings.TrimSpace(s[i:])
	if remaining != "" {
		// extra after path before "=" should be considered as not part of path? Actually for "json.a 1", after parsing "json.a", remaining "1" would be non-empty, but we want to treat as missing "="
		// So we return path and remaining
		// Caller will handle missing "="
	}

