func outputJSON(v interface{}, color bool) {
	if !color {
		b, err := json.MarshalIndent(v, "", "  ")
		if err != nil {
			fmt.Fprintf(os.Stderr, "failed to encode JSON: %s\n", err.Error())
			os.Exit(6)
		}
		fmt.Println(string(b))
	} else {
		// colored
		// Use custom pretty printer with color
		var buf bytes.Buffer
		writeColoredJSON(&buf, v, 0)
		buf.WriteString("\n")
		fmt.Print(buf.String())
	}
}

func writeColoredJSON(buf *bytes.Buffer, v interface{}, indent int) {
	magentaStart := "\x1b[35m"
	magentaEnd := "\x1b[0m"
	blueStart := "\x1b[34;1m"
	blueEnd := "\x1b[0;22m"
	yellowStart := "\x1b[33m"
	yellowEnd := "\x1b[0m"
	redStart := "\x1b[31m"
	redEnd := "\x1b[0m"
	cyanStart := "\x1b[36m"
	cyanEnd := "\x1b[0m"
	boldStart := "\x1b[1m"
	boldEnd := "\x1b[22m"
	greenStart := "\x1b[32m"
	greenEnd := "\x1b[0m"

	switch val := v.(type) {
	case map[string]interface{}:
		if len(val) == 0 {
			buf.WriteString(magentaStart + "{" + magentaEnd + magentaStart + "}" + magentaEnd)
			return
		}
		buf.WriteString(magentaStart + "{" + magentaEnd + "\n")
		keys := make([]string, 0, len(val))
		for k := range val {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for i, k := range keys {
			buf.WriteString(strings.Repeat("  ", indent+1))
			// key as blue bold: need to marshal key to JSON string to get escaped content, then split into quotes and content
			b, _ := marshalJSONWithEscape(k)
			// b is like "\"a\""
			// content is without first and last quote
			// For simplicity, we will output blue bold for opening quote, content, closing quote separately
			// Extract content between quotes: need to handle escapes? For key, content may contain escapes, but we can still output the whole quoted string as blue bold in three parts? Let's attempt to extract inner content as raw JSON string without outer quotes: e.g., "\"a\"" -> inner "a"
			// We can get inner by trimming first and last char, but need to preserve escapes inside
			// For "\"a\"" inner is "a"
			// For key with special chars, inner may contain escaped sequences like "\n" etc, which are part of content
			// So we can do: innerContent = string(b[1 : len(b)-1])

			inner := string(b[1 : len(b)-1])
			buf.WriteString(blueStart + "\"" + blueEnd)
			buf.WriteString(blueStart + inner + blueEnd)
			buf.WriteString(blueStart + "\"" + blueEnd)
			buf.WriteString(boldStart + ":" + boldEnd)
			buf.WriteString(" ")
			writeColoredJSON(buf, val[k], indent+1)
			if i < len(keys)-1 {
				buf.WriteString(boldStart + "," + boldEnd)
			}
			buf.WriteString("\n")
		}
		buf.WriteString(strings.Repeat("  ", indent))
		buf.WriteString(magentaStart + "}" + magentaEnd)
	case []interface{}:
		if len(val) == 0 {
			buf.WriteString(magentaStart + "[" + magentaEnd + magentaStart + "]" + magentaEnd)
			return
		}
		buf.WriteString(magentaStart + "[" + magentaEnd + "\n")
		for i, elem := range val {
			buf.WriteString(strings.Repeat("  ", indent+1))
			writeColoredJSON(buf, elem, indent+1)
			if i < len(val)-1 {
				buf.WriteString(boldStart + "," + boldEnd)
			}
			buf.WriteString("\n")
		}
		buf.WriteString(strings.Repeat("  ", indent))
		buf.WriteString(magentaStart + "]" + magentaEnd)
	case string:
		b, _ := marshalJSONWithEscape(val)
		// b is "\"hi\""
		inner := string(b[1 : len(b)-1])
		buf.WriteString(greenStart + "\"" + greenEnd)
		buf.WriteString(yellowStart + inner + yellowEnd)
		buf.WriteString(greenStart + "\"" + greenEnd)
	case json.Number:
		buf.WriteString(redStart + val.String() + redEnd)
	case bool:
		if val {
			buf.WriteString(cyanStart + "true" + cyanEnd)
		} else {
			buf.WriteString(cyanStart + "false" + cyanEnd)
		}
	case nil:
		buf.WriteString(cyanStart + "null" + cyanEnd)
	default:
		// try to handle other types (float64, etc) that may appear from json unmarshaling without UseNumber?
		switch x := val.(type) {
		case float64:
			buf.WriteString(redStart + strconv.FormatFloat(x, 'f', -1, 64) + redEnd)
		case int:
			buf.WriteString(redStart + strconv.Itoa(x) + redEnd)
		default:
			b, _ := marshalJSONWithEscape(val)
			buf.WriteString(string(b))
		}
	}

	// The above uses yellowStart, etc - need to define before
	_ = yellowStart
	_ = yellowEnd
	_ = redStart
	_ = redEnd
	_ = cyanStart
	_ = cyanEnd
	_ = greenStart
	_ = greenEnd
}

