actions.command:
cd /workspace
# Update handleValuesText and handleUngronText to ignore trailing empty line

cat > main.go <<'GO'
package main

import (
	"bufio"
	"bytes"
	"crypto/tls"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode"
	"unicode/utf8"
)

var helpText = `Transform JSON (from a file, URL, or stdin) into discrete assignments to make it greppable

Usage:
  gron [OPTIONS] [FILE|URL|-]

Options:
  -u, --ungron     Reverse the operation (turn assignments back into JSON)
  -v, --values     Print just the values of provided assignments
  -c, --colorize   Colorize output (default on tty)
  -m, --monochrome Monochrome (don't colorize output)
  -s, --stream     Treat each line of input as a separate JSON object
  -k, --insecure   Disable certificate validation
  -x, --proxy      Set proxy configuration
      --noproxy    Comma-separated list of hosts for which not to use a proxy, if one is specified.
  -j, --json       Represent gron data as JSON stream
      --no-sort    Don't sort output (faster)
      --version    Print version information

Exit Codes:
  0	OK
  1	Failed to open file
  2	Failed to read input
  3	Failed to form statements
  4	Failed to fetch URL
  5	Failed to parse statements
  6	Failed to encode JSON

Examples:
  gron /tmp/apiresponse.json
  gron http://jsonplaceholder.typicode.com/users/1 
  curl -s http://jsonplaceholder.typicode.com/users/1 | gron
  gron http://jsonplaceholder.typicode.com/users/1 | grep company | gron --ungron
`

func main() {
	fs := flag.NewFlagSet(os.Args[0], flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	fs.Usage = func() {
		fmt.Fprint(os.Stderr, helpText+"\n")
	}
	var ungron, values, colorize, monochrome, stream, insecure, jsonFlag, noSort, version, help bool
	var proxyStr, noproxyStr string
	fs.BoolVar(&ungron, "u", false, "")
	fs.BoolVar(&ungron, "ungron", false, "")
	fs.BoolVar(&values, "v", false, "")
	fs.BoolVar(&values, "values", false, "")
	fs.BoolVar(&colorize, "c", false, "")
	fs.BoolVar(&colorize, "colorize", false, "")
	fs.BoolVar(&monochrome, "m", false, "")
	fs.BoolVar(&monochrome, "monochrome", false, "")
	fs.BoolVar(&stream, "s", false, "")
	fs.BoolVar(&stream, "stream", false, "")
	fs.BoolVar(&insecure, "k", false, "")
	fs.BoolVar(&insecure, "insecure", false, "")
	fs.StringVar(&proxyStr, "x", "", "")
	fs.StringVar(&proxyStr, "proxy", "", "")
	fs.StringVar(&noproxyStr, "noproxy", "", "")
	fs.BoolVar(&jsonFlag, "j", false, "")
	fs.BoolVar(&jsonFlag, "json", false, "")
	fs.BoolVar(&noSort, "no-sort", false, "")
	fs.BoolVar(&version, "version", false, "")
	fs.BoolVar(&help, "h", false, "")
	fs.BoolVar(&help, "help", false, "")
	if err := fs.Parse(os.Args[1:]); err != nil {
		os.Exit(2)
	}
	if help {
		fmt.Fprint(os.Stderr, helpText+"\n")
		os.Exit(0)
	}
	if version {
		fmt.Println("gron version dev")
		os.Exit(0)
	}
	var fileArg string
	if fs.NArg() > 0 {
		fileArg = fs.Arg(0)
	}
	var inputBytes []byte
	var err error
	if fileArg == "" || fileArg == "-" {
		inputBytes, err = io.ReadAll(os.Stdin)
		if err != nil {
			fmt.Fprintf(os.Stderr, "failed to read input: %s\n", err.Error())
			os.Exit(2)
		}
	} else if strings.HasPrefix(fileArg, "http://") || strings.HasPrefix(fileArg, "https://") {
		inputBytes, err = fetchURL(fileArg, proxyStr, noproxyStr, insecure)
		if err != nil {
			fmt.Fprintln(os.Stderr, err.Error())
			os.Exit(4)
		}
	} else {
		f, e := os.Open(fileArg)
		if e != nil {
			fmt.Fprintln(os.Stderr, e.Error())
			os.Exit(1)
		}
		inputBytes, err = io.ReadAll(f)
		f.Close()
		if err != nil {
			fmt.Fprintf(os.Stderr, "failed to form statements: %s\n", err.Error())
			os.Exit(3)
		}
	}
	colorEnabled := false
	if values && !ungron {
		colorEnabled = false
	} else {
		if colorize {
			colorEnabled = true
		} else if monochrome {
			colorEnabled = false
		} else {
			if isTerminal(os.Stdout) {
				colorEnabled = true
			}
		}
	}
	if ungron {
		if jsonFlag {
			handleUngronJSONStream(inputBytes, colorEnabled)
		} else {
			handleUngronText(inputBytes, colorEnabled)
		}
	} else if values {
		handleValuesText(inputBytes)
	} else {
		if stream {
			handleGronStream(inputBytes, jsonFlag, noSort, colorEnabled)
		} else {
			handleGronSingle(inputBytes, jsonFlag, noSort, colorEnabled)
		}
	}
}

func isTerminal(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func fetchURL(rawurl, proxyStr, noproxyStr string, insecure bool) ([]byte, error) {
	var proxyURL *url.URL
	var err error
	if proxyStr != "" {
		proxyURL, err = url.Parse(proxyStr)
		if err != nil {
			return nil, fmt.Errorf("Get %q: %s", rawurl, err.Error())
		}
	}
	noproxyList := []string{}
	if noproxyStr != "" {
		for _, p := range strings.Split(noproxyStr, ",") {
			p = strings.TrimSpace(p)
			if p != "" {
				noproxyList = append(noproxyList, p)
			}
		}
	}
	transport := &http.Transport{TLSClientConfig: &tls.Config{}}
	if insecure {
		transport.TLSClientConfig.InsecureSkipVerify = true
	}
	transport.Proxy = func(req *http.Request) (*url.URL, error) {
		if proxyURL != nil {
			host := req.URL.Hostname()
			for _, np := range noproxyList {
				if np == "*" {
					return nil, nil
				}
				if host == np {
					return nil, nil
				}
				if strings.HasSuffix(host, "."+np) {
					return nil, nil
				}
			}
			return proxyURL, nil
		}
		return http.ProxyFromEnvironment(req)
	}
	client := &http.Client{Transport: transport, Timeout: 10 * time.Second}
	resp, err := client.Get(rawurl)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("Get %q: %s", rawurl, err.Error())
	}
	return body, nil
}

type OrderedMap struct {
	Keys   []string
	Values map[string]interface{}
}

func newOrderedMap() *OrderedMap {
	return &OrderedMap{Keys: []string{}, Values: map[string]interface{}{}}
}

func parseJSONValue(data []byte) (interface{}, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	val, err := parseValue(dec)
	if err != nil {
		return nil, err
	}
	return val, nil
}

func parseValue(dec *json.Decoder) (interface{}, error) {
	t, err := dec.Token()
	if err != nil {
		return nil, err
	}
	switch v := t.(type) {
	case json.Delim:
		switch v {
		case '{':
			om := newOrderedMap()
			for dec.More() {
				kt, err := dec.Token()
				if err != nil {
					return nil, err
				}
				key, ok := kt.(string)
				if !ok {
					return nil, fmt.Errorf("expected string key")
				}
				val, err := parseValue(dec)
				if err != nil {
					return nil, err
				}
				if _, exists := om.Values[key]; !exists {
					om.Keys = append(om.Keys, key)
				}
				om.Values[key] = val
			}
			_, err = dec.Token()
			if err != nil {
				return nil, err
			}
			return om, nil
		case '[':
			arr := []interface{}{}
			for dec.More() {
				val, err := parseValue(dec)
				if err != nil {
					return nil, err
				}
				arr = append(arr, val)
			}
			_, err = dec.Token()
			if err != nil {
				return nil, err
			}
			return arr, nil
		default:
			return nil, fmt.Errorf("unexpected delim %v", v)
		}
	case string:
		return v, nil
	case json.Number:
		return v, nil
	case bool:
		return v, nil
	case nil:
		return nil, nil
	default:
		return nil, fmt.Errorf("unexpected token %T", v)
	}
}

type Statement struct {
	PathStr   string
	PathSlice []interface{}
	Kind      int
	Primitive interface{}
}

const (
	KindEmptyObject = 0
	KindEmptyArray  = 1
	KindPrimitive   = 2
)

func (s Statement) TextLine(color bool) string {
	if color {
		var valStr string
		switch s.Kind {
		case KindEmptyObject:
			valStr = "\x1b[35m{}\x1b[0m"
		case KindEmptyArray:
			valStr = "\x1b[35m[]\x1b[0m"
		case KindPrimitive:
			valStr = formatPrimitiveForText(s.Primitive, true)
		}
		return fmt.Sprintf("%s = %s;", colorizePathText(s.PathSlice), valStr)
	}
	var valStr string
	switch s.Kind {
	case KindEmptyObject:
		valStr = "{}"
	case KindEmptyArray:
		valStr = "[]"
	case KindPrimitive:
		valStr = formatPrimitiveForText(s.Primitive, false)
	}
	return fmt.Sprintf("%s = %s;", s.PathStr, valStr)
}

func formatPrimitiveForText(v interface{}, color bool) string {
	switch x := v.(type) {
	case nil:
		if color {
			return "\x1b[36mnull\x1b[0m"
		}
		return "null"
	case bool:
		if x {
			if color {
				return "\x1b[36mtrue\x1b[0m"
			}
			return "true"
		}
		if color {
			return "\x1b[36mfalse\x1b[0m"
		}
		return "false"
	case string:
		b, _ := marshalJSONWithEscape(x)
		if color {
			return "\x1b[33m" + string(b) + "\x1b[0m"
		}
		return string(b)
	case json.Number:
		if color {
			return "\x1b[31m" + x.String() + "\x1b[0m"
		}
		return x.String()
	default:
		b, _ := marshalJSONWithEscape(v)
		return string(b)
	}
}

func marshalJSONWithEscape(v interface{}) ([]byte, error) {
	buf := &bytes.Buffer{}
	enc := json.NewEncoder(buf)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(v); err != nil {
		return nil, err
	}
	return bytes.TrimSpace(buf.Bytes()), nil
}

func colorizePathText(pathSlice []interface{}) string {
	blueStart := "\x1b[34;1m"
	blueEnd := "\x1b[0;22m"
	magentaStart := "\x1b[35m"
	magentaEnd := "\x1b[0m"
	yellowStart := "\x1b[33m"
	yellowEnd := "\x1b[0m"
	redStart := "\x1b[31m"
	redEnd := "\x1b[0m"
	var sb strings.Builder
	sb.WriteString(blueStart + "json" + blueEnd)
	for _, comp := range pathSlice {
		switch c := comp.(type) {
		case string:
			if isBareIdentifier(c) {
				sb.WriteString(".")
				sb.WriteString(blueStart + c + blueEnd)
			} else {
				b, _ := marshalJSONWithEscape(c)
				sb.WriteString(magentaStart + "[" + magentaEnd)
				sb.WriteString(yellowStart + string(b) + yellowEnd)
				sb.WriteString(magentaStart + "]" + magentaEnd)
			}
		case int:
			sb.WriteString(magentaStart + "[" + magentaEnd)
			sb.WriteString(redStart + strconv.Itoa(c) + redEnd)
			sb.WriteString(magentaStart + "]" + magentaEnd)
		}
	}
	return sb.String()
}

func (s Statement) JSONLine(color bool) string {
	if !color {
		var val interface{}
		switch s.Kind {
		case KindEmptyObject:
			val = map[string]interface{}{}
		case KindEmptyArray:
			val = []interface{}{}
		case KindPrimitive:
			val = s.Primitive
		}
		combined := []interface{}{s.PathSlice, val}
		b, _ := marshalJSONWithEscape(combined)
		return string(b)
	}
	magentaStart := "\x1b[35m"
	magentaEnd := "\x1b[0m"
	yellowStart := "\x1b[33m"
	yellowEnd := "\x1b[0m"
	redStart := "\x1b[31m"
	redEnd := "\x1b[0m"
	cyanStart := "\x1b[36m"
	cyanEnd := "\x1b[0m"
	var sb strings.Builder
	sb.WriteString(magentaStart + "[" + magentaEnd)
	sb.WriteString(magentaStart + "[" + magentaEnd)
	for i, comp := range s.PathSlice {
		if i > 0 {
			sb.WriteString(",")
		}
		switch c := comp.(type) {
		case string:
			b, _ := marshalJSONWithEscape(c)
			sb.WriteString(yellowStart + string(b) + yellowEnd)
		case int:
			sb.WriteString(redStart + strconv.Itoa(c) + redEnd)
		}
	}
	sb.WriteString(magentaStart + "]" + magentaEnd)
	sb.WriteString(",")
	switch s.Kind {
	case KindEmptyObject:
		sb.WriteString(magentaStart + "{}" + magentaEnd)
	case KindEmptyArray:
		sb.WriteString(magentaStart + "[]" + magentaEnd)
	case KindPrimitive:
		switch x := s.Primitive.(type) {
		case nil:
			sb.WriteString(cyanStart + "null" + cyanEnd)
		case bool:
			if x {
				sb.WriteString(cyanStart + "true" + cyanEnd)
			} else {
				sb.WriteString(cyanStart + "false" + cyanEnd)
			}
		case string:
			b, _ := marshalJSONWithEscape(x)
			sb.WriteString(yellowStart + string(b) + yellowEnd)
		case json.Number:
			sb.WriteString(redStart + x.String() + redEnd)
		}
	}
	sb.WriteString(magentaStart + "]" + magentaEnd)
	return sb.String()
}

func comparePaths(a, b []interface{}) int {
	la, lb := len(a), len(b)
	m := la
	if lb < m {
		m = lb
	}
	for i := 0; i < m; i++ {
		switch av := a[i].(type) {
		case string:
			switch bv := b[i].(type) {
			case string:
				if av < bv {
					return -1
				}
				if av > bv {
					return 1
				}
			case int:
				return -1
			}
		case int:
			switch bv := b[i].(type) {
			case int:
				if av < bv {
					return -1
				}
				if av > bv {
					return 1
				}
			case string:
				return 1
			}
		}
	}
	if la < lb {
		return -1
	}
	if la > lb {
		return 1
	}
	return 0
}

func genStatements(pathStr string, pathSlice []interface{}, val interface{}, out *[]Statement, noSort bool) {
	switch v := val.(type) {
	case *OrderedMap:
		if len(v.Keys) == 0 {
			*out = append(*out, Statement{PathStr: pathStr, PathSlice: pathSlice, Kind: KindEmptyObject})
		} else {
			*out = append(*out, Statement{PathStr: pathStr, PathSlice: pathSlice, Kind: KindEmptyObject})
			keys := v.Keys
			if !noSort {
				sorted := make([]string, len(keys))
				copy(sorted, keys)
				sort.Strings(sorted)
				keys = sorted
			}
			for _, k := range keys {
				childVal, ok := v.Values[k]
				if !ok {
					continue
				}
				var childPathStr string
				if isBareIdentifier(k) {
					childPathStr = pathStr + "." + k
				} else {
					b, _ := marshalJSONWithEscape(k)
					childPathStr = pathStr + "[" + string(b) + "]"
				}
				childPathSlice := append(append([]interface{}{}, pathSlice...), k)
				genStatements(childPathStr, childPathSlice, childVal, out, noSort)
			}
		}
	case []interface{}:
		if len(v) == 0 {
			*out = append(*out, Statement{PathStr: pathStr, PathSlice: pathSlice, Kind: KindEmptyArray})
		} else {
			*out = append(*out, Statement{PathStr: pathStr, PathSlice: pathSlice, Kind: KindEmptyArray})
			for i, elem := range v {
				childPathStr := pathStr + "[" + strconv.Itoa(i) + "]"
				childPathSlice := append(append([]interface{}{}, pathSlice...), i)
				genStatements(childPathStr, childPathSlice, elem, out, noSort)
			}
		}
	case nil:
		*out = append(*out, Statement{PathStr: pathStr, PathSlice: pathSlice, Kind: KindPrimitive, Primitive: nil})
	case bool:
		*out = append(*out, Statement{PathStr: pathStr, PathSlice: pathSlice, Kind: KindPrimitive, Primitive: v})
	case string:
		*out = append(*out, Statement{PathStr: pathStr, PathSlice: pathSlice, Kind: KindPrimitive, Primitive: v})
	case json.Number:
		*out = append(*out, Statement{PathStr: pathStr, PathSlice: pathSlice, Kind: KindPrimitive, Primitive: v})
	}
}

var reservedWords = map[string]bool{
	"break": true, "case": true, "catch": true, "class": true, "const": true,
	"continue": true, "debugger": true, "default": true, "delete": true, "do": true,
	"else": true, "export": true, "extends": true, "false": true, "finally": true,
	"for": true, "function": true, "if": true, "import": true, "in": true,
	"instanceof": true, "new": true, "null": true, "return": true, "super": true,
	"switch": true, "this": true, "throw": true, "true": true, "try": true,
	"typeof": true, "var": true, "void": true, "while": true, "with": true,
	"yield": true,
}

func isBareIdentifier(s string) bool {
	if s == "" {
		return false
	}
	if reservedWords[s] {
		return false
	}
	for i, r := range s {
		if i == 0 {
			if r == '_' || r == '$' || unicode.IsLetter(r) {
				continue
			}
			return false
		} else {
			if r == '_' || r == '$' || unicode.IsLetter(r) || unicode.IsDigit(r) {
				continue
			}
			return false
		}
	}
	return true
}

func handleGronSingle(input []byte, jsonFlag, noSort, colorEnabled bool) {
	if len(bytes.TrimSpace(input)) == 0 {
		fmt.Fprintln(os.Stderr, "failed to form statements: EOF")
		os.Exit(3)
	}
	val, err := parseJSONValue(input)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to form statements: %s\n", err.Error())
		os.Exit(3)
	}
	stmts := []Statement{}
	genStatements("json", []interface{}{}, val, &stmts, noSort)
	if !noSort {
		sort.Slice(stmts, func(i, j int) bool {
			return comparePaths(stmts[i].PathSlice, stmts[j].PathSlice) < 0
		})
	}
	if jsonFlag {
		for _, st := range stmts {
			fmt.Println(st.JSONLine(colorEnabled))
		}
	} else {
		for _, st := range stmts {
			fmt.Println(st.TextLine(colorEnabled))
		}
	}
}

func handleGronStream(input []byte, jsonFlag, noSort, colorEnabled bool) {
	if len(input) == 0 {
		stmts := []Statement{}
		genStatements("json", []interface{}{}, []interface{}{}, &stmts, noSort)
		if !noSort {
			sort.Slice(stmts, func(i, j int) bool {
				return comparePaths(stmts[i].PathSlice, stmts[j].PathSlice) < 0
			})
		}
		if jsonFlag {
			for _, st := range stmts {
				fmt.Println(st.JSONLine(colorEnabled))
			}
		} else {
			for _, st := range stmts {
				fmt.Println(st.TextLine(colorEnabled))
			}
		}
		return
	}
	scanner := bufio.NewScanner(bytes.NewReader(input))
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 10*1024*1024)
	var values []interface{}
	var firstErr error
	for scanner.Scan() {
		line := scanner.Text()
		if strings.TrimSpace(line) == "" {
			_, err := parseJSONValue([]byte(line))
			if err != nil {
				firstErr = err
				break
			}
			continue
		}
		val, err := parseJSONValue([]byte(line))
		if err != nil {
			firstErr = err
			break
		}
		values = append(values, val)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "failed to form statements: %s\n", err.Error())
		os.Exit(3)
	}
	if firstErr != nil {
		stmts := []Statement{}
		genStatements("json", []interface{}{}, values, &stmts, noSort)
		if !noSort {
			sort.Slice(stmts, func(i, j int) bool {
				return comparePaths(stmts[i].PathSlice, stmts[j].PathSlice) < 0
			})
		}
		if jsonFlag {
			for _, st := range stmts {
				fmt.Println(st.JSONLine(colorEnabled))
			}
		} else {
			for _, st := range stmts {
				fmt.Println(st.TextLine(colorEnabled))
			}
		}
		fmt.Fprintf(os.Stderr, "failed to form statements: %s\n", firstErr.Error())
		os.Exit(3)
	}
	stmts := []Statement{}
	genStatements("json", []interface{}{}, values, &stmts, noSort)
	if !noSort {
		sort.Slice(stmts, func(i, j int) bool {
			return comparePaths(stmts[i].PathSlice, stmts[j].PathSlice) < 0
		})
	}
	if jsonFlag {
		for _, st := range stmts {
			fmt.Println(st.JSONLine(colorEnabled))
		}
	} else {
		for _, st := range stmts {
			fmt.Println(st.TextLine(colorEnabled))
		}
	}
}

// Ungron

type ParsedStatement struct {
	Path          []interface{}
	IsEmptyObject bool
	IsEmptyArray  bool
	Primitive     interface{}
}

func handleUngronText(input []byte, colorEnabled bool) {
	lines := splitLinesForUngron(string(input))
	var parsed []ParsedStatement
	for _, line := range lines {
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, " ") {
			continue
		}
		if strings.HasPrefix(line, "\t") {
			fmt.Fprintln(os.Stderr, "ungron failed for ``: invalid statement")
			os.Exit(5)
		}
		semiIdx := findSemicolonOutsideString(line)
		if semiIdx == -1 {
			fmt.Fprintf(os.Stderr, "ungron failed for `%s`: statement has no value\n", line)
			os.Exit(5)
		}
		stmtStr := line[:semiIdx+1]
		ps, errMsg := parseGronStatement(stmtStr)
		if errMsg != "" {
			fmt.Fprintln(os.Stderr, errMsg)
			os.Exit(5)
		}
		parsed = append(parsed, ps)
	}
	if len(parsed) == 0 {
		fmt.Fprintln(os.Stderr, "no statements were parsed")
		os.Exit(5)
	}
	merged, err := mergeStatements(parsed)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to merge statements: %s\n", err.Error())
		os.Exit(5)
	}
	outputJSON(merged, colorEnabled)
}

func splitLinesForUngron(s string) []string {
	// Split by \n, remove final empty if input ends with \n (like gron does)
	if s == "" {
		return []string{}
	}
	parts := strings.Split(s, "\n")
	// If last part is empty (trailing newline), remove it
	if len(parts) > 0 && parts[len(parts)-1] == "" {
		parts = parts[:len(parts)-1]
	}
	return parts
}

func handleUngronJSONStream(input []byte, colorEnabled bool) {
	lines := splitLinesForUngron(string(input))
	var parsed []ParsedStatement
	for _, rawLine := range lines {
		line := strings.TrimSpace(rawLine)
		if line == "" {
			continue
		}
		var arr []interface{}
		dec := json.NewDecoder(strings.NewReader(line))
		dec.UseNumber()
		if err := dec.Decode(&arr); err != nil {
			fmt.Fprintln(os.Stderr, err.Error())
			os.Exit(5)
		}
		if len(arr) != 2 {
			fmt.Fprintln(os.Stderr, "invalid statement")
			os.Exit(5)
		}
		pathRaw, ok := arr[0].([]interface{})
		if !ok {
			fmt.Fprintln(os.Stderr, "invalid statement")
			os.Exit(5)
		}
		path := []interface{}{}
		for _, p := range pathRaw {
			switch v := p.(type) {
			case string:
				path = append(path, v)
			case json.Number:
				i, err := v.Int64()
				if err == nil {
					path = append(path, int(i))
				} else {
					f, _ := v.Float64()
					path = append(path, int(f))
				}
			case float64:
				path = append(path, int(v))
			default:
				path = append(path, fmt.Sprintf("%v", v))
			}
		}
		val := arr[1]
		ps := ParsedStatement{Path: path}
		switch vv := val.(type) {
		case map[string]interface{}:
			if len(vv) == 0 {
				ps.IsEmptyObject = true
			} else {
				ps.IsEmptyObject = true
			}
		case []interface{}:
			if len(vv) == 0 {
				ps.IsEmptyArray = true
			} else {
				ps.IsEmptyArray = true
			}
		case nil:
			ps.Primitive = nil
		case bool:
			ps.Primitive = vv
		case string:
			ps.Primitive = vv
		case json.Number:
			ps.Primitive = vv
		default:
			ps.Primitive = vv
		}
		parsed = append(parsed, ps)
	}
	if len(parsed) == 0 {
		fmt.Fprintln(os.Stderr, "no statements were parsed")
		os.Exit(5)
	}
	merged, err := mergeStatements(parsed)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to merge statements: %s\n", err.Error())
		os.Exit(5)
	}
	outputJSON(merged, colorEnabled)
}

func handleValuesText(input []byte) {
	lines := splitLinesForUngron(string(input))
	if len(lines) == 0 {
		return
	}
	for _, rawLine := range lines {
		line := rawLine
		if line == "" {
			fmt.Fprintln(os.Stderr, "failed to parse '' as gron statement")
			os.Exit(5)
		}
		if strings.HasPrefix(line, " ") {
			fmt.Fprintf(os.Stderr, "failed to parse '%s' as gron statement\n", line)
			os.Exit(5)
		}
		if strings.HasPrefix(line, "\t") {
			continue
		}
		semiIdx := findSemicolonOutsideString(line)
		var stmtPart string
		if semiIdx == -1 {
			stmtPart = line
		} else {
			stmtPart = line[:semiIdx]
		}
		eqIdx := findEqualOutsideString(stmtPart)
		if eqIdx == -1 {
			continue
		}
		pathPart := stmtPart[:eqIdx]
		valuePart := stmtPart[eqIdx+1:]
		_, _, perr := parsePath(pathPart)
		if perr != "" {
			continue
		}
		leadTrimmed := strings.TrimLeft(valuePart, " \t")
		if leadTrimmed == "" {
			continue
		}
		first := leadTrimmed[0]
		if (first >= '0' && first <= '9') || first == '-' {
			fmt.Println(leadTrimmed)
		} else {
			trimmed := strings.TrimSpace(valuePart)
			if trimmed == "{}" || trimmed == "[]" {
				continue
			}
			dec := json.NewDecoder(strings.NewReader(trimmed))
			dec.UseNumber()
			var v interface{}
			if err := dec.Decode(&v); err != nil {
				continue
			}
			switch vv := v.(type) {
			case string:
				fmt.Println(vv)
			case bool:
				if vv {
					fmt.Println("true")
				} else {
					fmt.Println("false")
				}
			case nil:
				fmt.Println("null")
			case json.Number:
				fmt.Println(vv.String())
			default:
				continue
			}
		}
	}
}

func findSemicolonOutsideString(s string) int {
	inStr := false
	esc := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if esc {
			esc = false
			continue
		}
		if c == '\\' && inStr {
			esc = true
			continue
		}
		if c == '"' {
			inStr = !inStr
			continue
		}
		if !inStr && c == ';' {
			return i
		}
	}
	return -1
}

func findEqualOutsideString(s string) int {
	inStr := false
	esc := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if esc {
			esc = false
			continue
		}
		if c == '\\' && inStr {
			esc = true
			continue
		}
		if c == '"' {
			inStr = !inStr
			continue
		}
		if !inStr && c == '=' {
			return i
		}
	}
	return -1
}

func parseGronStatement(stmt string) (ParsedStatement, string) {
	inner := stmt[:len(stmt)-1]
	eqIdx := findEqualOutsideString(inner)
	if eqIdx == -1 {
		spaceIdx := strings.Index(inner, " ")
		var pathPart string
		if spaceIdx != -1 {
			pathPart = strings.TrimSpace(inner[:spaceIdx])
		} else {
			pathPart = strings.TrimSpace(inner)
		}
		if pathPart == "" {
			return ParsedStatement{}, fmt.Sprintf("ungron failed for `%s`: statement has no value", inner)
		}
		_, _, perr := parsePath(inner)
		if perr != "" {
			return ParsedStatement{}, perr
		}
		return ParsedStatement{}, fmt.Sprintf("ungron failed for `%s`: statement has no value", pathPart)
	}
	pathPart := inner[:eqIdx]
	valuePart := inner[eqIdx+1:]
	pathSlice, _, perr := parsePath(pathPart)
	if perr != "" {
		return ParsedStatement{}, perr
	}
	trimmedValue := strings.TrimSpace(valuePart)
	if trimmedValue == "" {
		return ParsedStatement{}, fmt.Sprintf("ungron failed for `%s`: statement has no value", inner)
	}
	if trimmedValue == "{}" {
		return ParsedStatement{Path: pathSlice, IsEmptyObject: true}, ""
	}
	if trimmedValue == "[]" {
		return ParsedStatement{Path: pathSlice, IsEmptyArray: true}, ""
	}
	if trimmedValue == "{" || trimmedValue == "[" {
		return ParsedStatement{}, fmt.Sprintf("ungron failed for `%s`: invalid value `%s`", stmt, trimmedValue)
	}
	if strings.HasPrefix(trimmedValue, "{") || strings.HasPrefix(trimmedValue, "[") {
		pp := strings.TrimSpace(pathPart)
		return ParsedStatement{}, fmt.Sprintf("ungron failed for `%s = %c`: statement has no value", pp, trimmedValue[0])
	}
	if isNumberStart(trimmedValue) {
		numStr := extractNumberPrefix(trimmedValue)
		if numStr != "" {
			return ParsedStatement{Path: pathSlice, Primitive: json.Number(numStr)}, ""
		}
	}
	dec := json.NewDecoder(strings.NewReader(trimmedValue))
	dec.UseNumber()
	var v interface{}
	if err := dec.Decode(&v); err != nil {
		return ParsedStatement{}, fmt.Sprintf("ungron failed for `%s`: invalid value `%s`", stmt, trimmedValue)
	}
	b, _ := marshalJSONWithEscape(v)
	ms := string(b)
	rest := ""
	if strings.HasPrefix(trimmedValue, ms) {
		rest = strings.TrimSpace(trimmedValue[len(ms):])
	}
	if rest != "" {
		pp := strings.TrimSpace(pathPart)
		return ParsedStatement{}, fmt.Sprintf("ungron failed for `%s = %s`: statement has no value", pp, ms)
	}
	switch vv := v.(type) {
	case string:
		return ParsedStatement{Path: pathSlice, Primitive: vv}, ""
	case bool:
		return ParsedStatement{Path: pathSlice, Primitive: vv}, ""
	case nil:
		return ParsedStatement{Path: pathSlice, Primitive: nil}, ""
	case json.Number:
		return ParsedStatement{Path: pathSlice, Primitive: vv}, ""
	default:
		pp := strings.TrimSpace(pathPart)
		return ParsedStatement{}, fmt.Sprintf("ungron failed for `%s = %c`: statement has no value", pp, trimmedValue[0])
	}
}

func isNumberStart(s string) bool {
	if s == "" {
		return false
	}
	c := s[0]
	return (c >= '0' && c <= '9') || c == '-'
}

func extractNumberPrefix(s string) string {
	i := 0
	if i < len(s) && s[i] == '-' {
		i++
	}
	if i >= len(s) {
		return ""
	}
	if s[i] == '0' {
		i++
	} else if s[i] >= '1' && s[i] <= '9' {
		i++
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			i++
		}
	} else {
		return ""
	}
	if i < len(s) && s[i] == '.' {
		if i+1 < len(s) && s[i+1] >= '0' && s[i+1] <= '9' {
			i++
			for i < len(s) && s[i] >= '0' && s[i] <= '9' {
				i++
			}
		}
	}
	if i < len(s) && (s[i] == 'e' || s[i] == 'E') {
		j := i + 1
		if j < len(s) && (s[j] == '+' || s[j] == '-') {
			j++
		}
		if j < len(s) && s[j] >= '0' && s[j] <= '9' {
			i = j + 1
			for i < len(s) && s[i] >= '0' && s[i] <= '9' {
				i++
			}
		}
	}
	return s[:i]
}

func parsePath(s string) ([]interface{}, string, string) {
	orig := s
	s = strings.TrimSpace(s)
	if s == "" {
		return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", orig)
	}
	var path []interface{}
	i := 0
	// first ident
	start := i
	if i >= len(s) {
		return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i))
	}
	r, size := utf8.DecodeRuneInString(s[i:])
	if !isIdentifierStart(r) {
		return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i))
	}
	i += size
	for i < len(s) {
		r, size := utf8.DecodeRuneInString(s[i:])
		if isIdentifierChar(r) {
			i += size
		} else {
			break
		}
	}
	ident := s[start:i]
	path = append(path, ident)
	for i < len(s) {
		for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
			i++
		}
		if i >= len(s) {
			break
		}
		ch := s[i]
		if ch == '.' {
			i++
			if i >= len(s) {
				return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i))
			}
			if s[i] == '.' {
				return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i-1))
			}
			start2 := i
			r, _ := utf8.DecodeRuneInString(s[i:])
			if !isIdentifierStart(r) {
				return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, start2-1))
			}
			for i < len(s) {
				r, size := utf8.DecodeRuneInString(s[i:])
				if isIdentifierChar(r) {
					i += size
				} else {
					break
				}
			}
			ident2 := s[start2:i]
			path = append(path, ident2)
		} else if ch == '[' {
			i++
			for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
				i++
			}
			if i >= len(s) {
				return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i-1))
			}
			if s[i] == '"' {
				strStart := i
				j := i + 1
				esc := false
				found := false
				for j < len(s) {
					c := s[j]
					if esc {
						esc = false
						j++
						continue
					}
					if c == '\\' {
						esc = true
						j++
						continue
					}
					if c == '"' {
						found = true
						break
					}
					j++
				}
				if !found {
					return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", s[:strStart])
				}
				strLit := s[strStart : j+1]
				var key string
				if err := json.Unmarshal([]byte(strLit), &key); err != nil {
					return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", s[:j+1])
				}
				path = append(path, key)
				i = j + 1
				for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
					i++
				}
				if i >= len(s) || s[i] != ']' {
					return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i))
				}
				i++
			} else if s[i] >= '0' && s[i] <= '9' {
				numStart := i
				for i < len(s) && s[i] >= '0' && s[i] <= '9' {
					i++
				}
				numStr := s[numStart:i]
				idx, _ := strconv.Atoi(numStr)
				path = append(path, idx)
				for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
					i++
				}
				if i >= len(s) || s[i] != ']' {
					return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i))
				}
				i++
			} else {
				return nil, "", fmt.Sprintf("ungron failed for `%s`: invalid statement", getPartialPath(s, i-1))
			}
		} else {
			break
		}
	}
	remaining := strings.TrimSpace(s[i:])
	if len(path) > 0 {
		if first, ok := path[0].(string); ok && first == "json" {
			path = path[1:]
		}
	}
	return path, remaining, ""
}

func getPartialPath(s string, idx int) string {
	if idx < 0 {
		idx = 0
	}
	if idx > len(s) {
		idx = len(s)
	}
	return s[:idx]
}

func isIdentifierStart(r rune) bool {
	return r == '_' || r == '$' || unicode.IsLetter(r)
}
func isIdentifierChar(r rune) bool {
	return r == '_' || r == '$' || unicode.IsLetter(r) || unicode.IsDigit(r)
}

func mergeStatements(stmts []ParsedStatement) (interface{}, error) {
	var root interface{} = nil
	for _, st := range stmts {
		if len(st.Path) == 0 {
			if st.IsEmptyObject {
				if root == nil {
					root = map[string]interface{}{}
				} else {
					if _, ok := root.(map[string]interface{}); !ok {
						if _, isArr := root.([]interface{}); isArr {
							return nil, fmt.Errorf("cannot merge object with non-object")
						}
					}
				}
			} else if st.IsEmptyArray {
				if root == nil {
					root = []interface{}{}
				} else {
					if _, ok := root.([]interface{}); !ok {
						if _, isMap := root.(map[string]interface{}); isMap {
							return nil, fmt.Errorf("cannot merge array with non-array")
						}
					}
				}
			} else {
				root = st.Primitive
			}
		} else {
			if root == nil {
				if _, isInt := st.Path[0].(int); isInt {
					root = []interface{}{}
				} else {
					root = map[string]interface{}{}
				}
			}
			if err := setValueAtPath(&root, st.Path, st); err != nil {
				return nil, err
			}
		}
	}
	return root, nil
}

func setValueAtPath(root *interface{}, path []interface{}, st ParsedStatement) error {
	var helper func(cur *interface{}, p []interface{}) error
	helper = func(cur *interface{}, p []interface{}) error {
		if len(p) == 0 {
			return nil
		}
		comp := p[0]
		isLast := len(p) == 1
		switch c := comp.(type) {
		case string:
			if *cur == nil {
				*cur = map[string]interface{}{}
			}
			m, ok := (*cur).(map[string]interface{})
			if !ok {
				if _, isArr := (*cur).([]interface{}); isArr {
					return fmt.Errorf("cannot merge object with non-object")
				}
				m = map[string]interface{}{}
				*cur = m
			}
			if isLast {
				if st.IsEmptyObject {
					if existing, exists := m[c]; !exists {
						m[c] = map[string]interface{}{}
					} else {
						if _, isArr := existing.([]interface{}); isArr {
							return fmt.Errorf("cannot merge object with non-object")
						}
						if _, isMap := existing.(map[string]interface{}); !isMap {
							m[c] = map[string]interface{}{}
						}
					}
				} else if st.IsEmptyArray {
					if existing, exists := m[c]; !exists {
						m[c] = []interface{}{}
					} else {
						if _, isMap := existing.(map[string]interface{}); isMap {
							return fmt.Errorf("cannot merge array with non-array")
						}
						if _, isArr := existing.([]interface{}); !isArr {
							m[c] = []interface{}{}
						}
					}
				} else {
					m[c] = st.Primitive
				}
				return nil
			}
			next := p[1]
			existing, exists := m[c]
			if !exists {
				if _, isInt := next.(int); isInt {
					m[c] = []interface{}{}
				} else {
					m[c] = map[string]interface{}{}
				}
				existing = m[c]
			} else {
				if _, isInt := next.(int); isInt {
					if _, isMap := existing.(map[string]interface{}); isMap {
						return fmt.Errorf("cannot merge array with non-array")
					}
					if _, isArr := existing.([]interface{}); !isArr {
						m[c] = []interface{}{}
						existing = m[c]
					}
				} else {
					if _, isArr := existing.([]interface{}); isArr {
						return fmt.Errorf("cannot merge object with non-object")
					}
					if _, isMap := existing.(map[string]interface{}); !isMap {
						m[c] = map[string]interface{}{}
						existing = m[c]
					}
				}
			}
			nextCur := existing
			if err := helper(&nextCur, p[1:]); err != nil {
				return err
			}
			m[c] = nextCur
			*cur = m
			return nil
		case int:
			if *cur == nil {
				*cur = []interface{}{}
			}
			arr, ok := (*cur).([]interface{})
			if !ok {
				if _, isMap := (*cur).(map[string]interface{}); isMap {
					return fmt.Errorf("cannot merge array with non-array")
				}
				arr = []interface{}{}
				*cur = arr
			}
			for len(arr) <= c {
				arr = append(arr, nil)
			}
			*cur = arr
			arr = (*cur).([]interface{})
			if isLast {
				if st.IsEmptyObject {
					if arr[c] == nil {
						arr[c] = map[string]interface{}{}
					} else {
						if _, isArr := arr[c].([]interface{}); isArr {
							return fmt.Errorf("cannot merge object with non-object")
						}
						if _, isMap := arr[c].(map[string]interface{}); !isMap {
							arr[c] = map[string]interface{}{}
						}
					}
					*cur = arr
				} else if st.IsEmptyArray {
					if arr[c] == nil {
						arr[c] = []interface{}{}
					} else {
						if _, isMap := arr[c].(map[string]interface{}); isMap {
							return fmt.Errorf("cannot merge array with non-array")
						}
						if _, isArr := arr[c].([]interface{}); !isArr {
							arr[c] = []interface{}{}
						}
					}
					*cur = arr
				} else {
					arr[c] = st.Primitive
					*cur = arr
				}
				return nil
			}
			next := p[1]
			existing := arr[c]
			if existing == nil {
				if _, isInt := next.(int); isInt {
					arr[c] = []interface{}{}
				} else {
					arr[c] = map[string]interface{}{}
				}
				*cur = arr
				existing = arr[c]
			} else {
				if _, isInt := next.(int); isInt {
					if _, isMap := existing.(map[string]interface{}); isMap {
						return fmt.Errorf("cannot merge array with non-array")
					}
					if _, isArr := existing.([]interface{}); !isArr {
						arr[c] = []interface{}{}
						*cur = arr
						existing = arr[c]
					}
				} else {
					if _, isArr := existing.([]interface{}); isArr {
						return fmt.Errorf("cannot merge object with non-object")
					}
					if _, isMap := existing.(map[string]interface{}); !isMap {
						arr[c] = map[string]interface{}{}
						*cur = arr
						existing = arr[c]
					}
				}
			}
			nextCur := existing
			if err := helper(&nextCur, p[1:]); err != nil {
				return err
			}
			arr[c] = nextCur
			*cur = arr
			return nil
		}
		return nil
	}
	return helper(root, path)
}

func outputJSON(v interface{}, color bool) {
	if !color {
		b, err := json.MarshalIndent(v, "", "  ")
		if err != nil {
			fmt.Fprintf(os.Stderr, "failed to encode JSON: %s\n", err.Error())
			os.Exit(6)
		}
		fmt.Println(string(b))
		return
	}
	var buf bytes.Buffer
	writeColoredJSON(&buf, v, 0)
	buf.WriteString("\n")
	fmt.Print(buf.String())
}

func writeColoredJSON(buf *bytes.Buffer, v interface{}, indent int) {
	magentaStart := "\x1b[35m"
	magentaEnd := "\x1b[0m"
	blueStart := "\x1b[34;1m"
	blueEnd := "\x1b[0;22m"
	yellowStart := "\x1b[33m"
	yellowEnd := "\x1b[0m"
	redStart := "\x1b[31m"
	redEnd := "\x1b[0m"
	cyanStart := "\x1b[36m"
	cyanEnd := "\x1b[0m"
	boldStart := "\x1b[1m"
	boldEnd := "\x1b[22m"
	greenStart := "\x1b[32m"
	greenEnd := "\x1b[0m"

	switch val := v.(type) {
	case map[string]interface{}:
		if len(val) == 0 {
			buf.WriteString(magentaStart + "{" + magentaEnd + magentaStart + "}" + magentaEnd)
			return
		}
		buf.WriteString(magentaStart + "{" + magentaEnd + "\n")
		keys := make([]string, 0, len(val))
		for k := range val {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for i, k := range keys {
			buf.WriteString(strings.Repeat("  ", indent+1))
			b, _ := marshalJSONWithEscape(k)
			inner := string(b[1 : len(b)-1])
			buf.WriteString(blueStart + "\"" + blueEnd)
			buf.WriteString(blueStart + inner + blueEnd)
			buf.WriteString(blueStart + "\"" + blueEnd)
			buf.WriteString(boldStart + ":" + boldEnd)
			buf.WriteString(" ")
			writeColoredJSON(buf, val[k], indent+1)
			if i < len(keys)-1 {
				buf.WriteString(boldStart + "," + boldEnd)
			}
			buf.WriteString("\n")
		}
		buf.WriteString(strings.Repeat("  ", indent))
		buf.WriteString(magentaStart + "}" + magentaEnd)
	case []interface{}:
		if len(val) == 0 {
			buf.WriteString(magentaStart + "[" + magentaEnd + magentaStart + "]" + magentaEnd)
			return
		}
		buf.WriteString(magentaStart + "[" + magentaEnd + "\n")
		for i, elem := range val {
			buf.WriteString(strings.Repeat("  ", indent+1))
			writeColoredJSON(buf, elem, indent+1)
			if i < len(val)-1 {
				buf.WriteString(boldStart + "," + boldEnd)
			}
			buf.WriteString("\n")
		}
		buf.WriteString(strings.Repeat("  ", indent))
		buf.WriteString(magentaStart + "]" + magentaEnd)
	case string:
		b, _ := marshalJSONWithEscape(val)
		inner := string(b[1 : len(b)-1])
		buf.WriteString(greenStart + "\"" + greenEnd)
		buf.WriteString(yellowStart + inner + yellowEnd)
		buf.WriteString(greenStart + "\"" + greenEnd)
	case json.Number:
		buf.WriteString(redStart + val.String() + redEnd)
	case bool:
		if val {
			buf.WriteString(cyanStart + "true" + cyanEnd)
		} else {
			buf.WriteString(cyanStart + "false" + cyanEnd)
		}
	case nil:
		buf.WriteString(cyanStart + "null" + cyanEnd)
	default:
		switch x := v.(type) {
		case float64:
			buf.WriteString(redStart + strconv.FormatFloat(x, 'f', -1, 64) + redEnd)
		case int:
			buf.WriteString(redStart + strconv.Itoa(x) + redEnd)
		default:
			b, _ := marshalJSONWithEscape(val)
			buf.WriteString(string(b))
		}
	}
}
