# Let's rewrite fetchURL entirely

cat > /tmp/fetch.go <<'GO'
func fetchURL(rawurl, proxyStr, noproxyStr string, insecure bool) ([]byte, error) {
	var proxyURL *url.URL
	var err error
	if proxyStr != "" {
		proxyURL, err = url.Parse(proxyStr)
		if err != nil {
			return nil, fmt.Errorf("Get %q: %s", rawurl, err.Error())
		}
	}
	noproxyList := []string{}
	if noproxyStr != "" {
		for _, p := range strings.Split(noproxyStr, ",") {
			p = strings.TrimSpace(p)
			if p != "" {
				noproxyList = append(noproxyList, p)
			}
		}
	}
	transport := &http.Transport{TLSClientConfig: &tls.Config{}}
	if insecure {
		transport.TLSClientConfig.InsecureSkipVerify = true
	}
	transport.Proxy = func(req *http.Request) (*url.URL, error) {
		if proxyURL != nil {
			host := req.URL.Host
			for _, np := range noproxyList {
				if np == "*" {
					return nil, nil
				}
				if host == np {
					return nil, nil
				}
			}
			return proxyURL, nil
		}
		return http.ProxyFromEnvironment(req)
	}
	client := &http.Client{Transport: transport, Timeout: 10 * time.Second}
	resp, err := client.Get(rawurl)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("Get %q: %s", rawurl, err.Error())
	}
	return body, nil
}
GO

python3 <<'PY'
with open('main.go','r') as f:
    content=f.read()
# find func fetchURL
import re
pattern = r'func fetchURL\(rawurl, proxyStr, noproxyStr string, insecure bool\) \(.*?^\}'
m=re.search(pattern, content, re.DOTALL | re.MULTILINE)
if m:
    print("found")
    print(m.group()[:500])
    with open('/tmp/fetch.go','r') as nf:
        newfunc=nf.read()
    newcontent = content[:m.start()] + newfunc + content[m.end():]
    with open('main.go','w') as out:
        out.write(newcontent)
    print("replaced")
else:
    print("not found")
